{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.logic_combined_inventory AS WITH store AS ( SELECT DATE::date AS date, LOT_MRP, PACKING, ITEM_MRP, LOT_CODE, ITEM_CF_1, ITEM_CF_2, ITEM_CF_3, ITEM_NAME, PACK_NAME as size, STOCK_QTY, LOT_NUMBER, SHADE_NAME, BRANCH_CODE, BRANCH_NAME, GODOWN_CODE, GODOWN_NAME, LOT_SPRATE1, ADDLITEMCODE , CARTON_STOCK, TRY_TO_DATE(LOT_PUR_DATE, \'DD/MM/YYYY\') AS LOT_PUR_DATE, LOGICUSERCODE as sku, LOT_SALE_RATE, ITEM_SALE_RATE, LOT_BASIC_RATE FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE DATE::date = current_date() ), warehouse_name AS ( SELECT DATE::date AS date, LOT_MRP, PACKING, ITEM_MRP, LOT_CODE, ITEM_CF_1, ITEM_CF_2, ITEM_CF_3, ITEM_NAME, PACK_NAME as size, STOCK_QTY, LOT_NUMBER, SHADE_NAME, BRANCH_CODE, BRANCH_NAME, GODOWN_CODE, GODOWN_NAME, LOT_SPRATE1, ADDLITEMCODE, CARTON_STOCK, TRY_TO_DATE(LOT_PUR_DATE, \'DD/MM/YYYY\') AS LOT_PUR_DATE, LOGICUSERCODE as sku, LOT_SALE_RATE, ITEM_SALE_RATE, LOT_BASIC_RATE FROM snitch_db.maplemonk.logicerp_warehouse_get_stock_in_hand WHERE DATE::date = current_date()-1 ) SELECT * FROM store UNION ALL SELECT * FROM warehouse_name; create or replace table snitch_db.maplemonk.logic_final_inventory as with item as ( select distinct sku_group, category_code from snitch_db.maplemonk.uc_final_item_master ), final as( SELECT LEFT(a.sku, LENGTH(a.sku) - CHARINDEX(\'-\', REVERSE(a.sku))) AS sku_group, c.price, c.sku_class, c.status, a.*, CASE WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 0 AND 30 THEN \'0-30\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 31 AND 60 THEN \'30-60\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 61 AND 90 THEN \'60-90\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 91 AND 120 THEN \'90-120\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 121 AND 150 THEN \'120-150\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 151 AND 180 THEN \'150-180\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 181 AND 210 THEN \'180-210\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 211 AND 240 THEN \'210-240\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 241 AND 270 THEN \'240-270\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 271 AND 300 THEN \'270-300\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 301 AND 330 THEN \'300-330\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 331 AND 360 THEN \'330-360\' ELSE \'360+\' END as ageing_group, case when branch_name like \'%SNITCH - WH%\' then \'WAREHOUSE\' when branch_name like \'%COFO%\' or branch_name like \'%FOCO%\' or branch_name like \'%COCO%\' then \'STORE\' else \'UNKOWN\' END AS Location_Type, CASE WHEN GODOWN_NAME like \'%BAD%\' or godown_name like \'%DAMAGED%\' THEN \'BAD\' ELSE \'GOOD\' end as inventory_type, i.category_code as category FROM snitch_db.maplemonk.logic_combined_inventory a LEFT JOIN snitch_db.maplemonk.availability_master_v2 AS c ON UPPER(TRIM(LEFT(a.sku, LENGTH(a.sku) - CHARINDEX(\'-\', REVERSE(a.sku))))) = c.\"SKU_GROUP\" LEFT JOIN item as i ON c.sku_group = i.sku_group) select * from final; create or replace table snitch_db.maplemonk.final_inventory as with am as ( select distinct sku_group, sku_class from snitch_db.maplemonk.availability_master_v2 ), item as ( select distinct sku_group, category_code from snitch_db.maplemonk.uc_final_item_master ), final as ( SELECT a.color, CAST(COALESCE(NULLIF(a.\"Cost Price\", \'\'), 0) AS INTEGER) AS \"Cost Price\", a.facility, a.enabled, CAST(COALESCE(NULLIF(a.inventory, \'\'), 0) AS INTEGER) AS inventory, CAST(COALESCE(NULLIF(a.\"Inventory Blocked\", \'\'), 0) AS INTEGER) AS \"InventoryBlocked\", CAST(COALESCE(NULLIF(a.\"Inventory Not Synced\", \'\'), 0) AS INTEGER) AS \"InventoryNotSynced\", CAST(COALESCE(NULLIF(a.\"Bad Inventory\", \'\'), 0) AS INTEGER) AS \"BadInventory\", CAST(COALESCE(NULLIF(a.\"Not Found\", \'\'), 0) AS INTEGER) AS \"NotFound\", CAST(COALESCE(NULLIF(a.\"Putaway Pending\", \'\'), 0) AS INTEGER) AS \"PutawayPending\", CAST(COALESCE(NULLIF(a.\"Putback Pending\", \'\'), 0) AS INTEGER) AS \"PutbackPending\", CAST(COALESCE(NULLIF(a.\"Stock In Transfer\", \'\'), 0) AS INTEGER) AS \"StockInTransfer\", ( CAST(COALESCE(NULLIF(a.inventory, \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Inventory Blocked\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Inventory Not Synced\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Bad Inventory\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Not Found\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Putaway Pending\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Putback Pending\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Stock In Transfer\", \'\'), 0) AS INTEGER) ) AS \"Total Inventory\", a.size, a.updated, a.date, a.\"Item SkuCode\" AS sku, a.mrp, CAST(COALESCE(NULLIF(a.\"GRN Price With Tax\", \'\'), 0) AS INTEGER) AS \"GRN Price With Tax\", CAST(COALESCE(NULLIF(a.\"GRN Price Without Tax\", \'\'), 0) AS INTEGER) AS \"GRN Price Without Tax\", c.sku_class, c.sku_group, i.category_code as category FROM snitch_db.maplemonk.snitch_final_inventory_wh2 AS a LEFT JOIN am AS c ON UPPER(TRIM(LEFT(a.\"Item SkuCode\", LENGTH(a.\"Item SkuCode\") - CHARINDEX(\'-\', REVERSE(a.\"Item SkuCode\"))))) = c.\"SKU_GROUP\" LEFT JOIN item as i ON c.sku_group = i.sku_group WHERE a.facility IN (\'SAPL-WH1\', \'SAPL-WH2\', \'SAPL_EMIZA\') AND a.date = current_date) select * from final ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            